#if APP_TESTS
using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class VendorUpdatesTests {
    static void Require(bool value,string label,List<string> log){if(!value)throw new Exception(label);log.Add(label);}
    static string Digest(string path){using(var file=File.OpenRead(path))return VendorUpdates.Hash(file);}
    static string Json(string url,string digest="sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",string tag="99.0",string name="7z9900-x64.exe") {return new JavaScriptSerializer().Serialize(new{tag_name=tag,draft=false,prerelease=false,body="Vendor fixture",assets=new[]{new{name=name,browser_download_url=url,digest=digest,size=1500000}}});}
    internal static int Run(string root,bool live){
        Directory.CreateDirectory(root);var log=new List<string>();MainWindow main=null;ConfigurationDialog settings=null;
        Action<bool,string> check=(valid,label)=>Require(valid,label,log);
        try{
            SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs-CZ");FluentTheme.Ensure();AppearanceTheme.Apply("Light");
            string official="https://github.com/ip7z/7zip/releases/download/99.0/7z9900-x64.exe";
            var item=VendorUpdates.Github("7zip",Json(official));check(item.Version=="99.0"&&item.Hash.Length==64&&VendorUpdates.ValidOrigin(item),"official GitHub release resolves one Windows x64 asset and publisher SHA-256");
            bool rejected=false;try{VendorUpdates.Github("7zip",Json("https://github.com/attacker/package/releases/download/99.0/7z9900-x64.exe"));}catch(IOException){rejected=true;}check(rejected,"release metadata cannot redirect initial package selection to another repository");
            var missing=VendorUpdates.Github("7zip",Json(official,null));check(!String.IsNullOrEmpty(missing.Error)&&missing.Hash==null,"missing publisher digest disables automatic installation");
            check(!UpdateNetwork.Allowed("http://github.com/file")&&!UpdateNetwork.Allowed("https://github.com.attacker.invalid/file")&&!UpdateNetwork.Allowed("https://user@github.com/file")&&!UpdateNetwork.Allowed("https://github.com:444/file"),"transport rejects HTTP, lookalike hosts, credentials and custom ports");
            foreach(string unsafePath in new[]{"..\\escape","C:\\escape","ok:ads","folder\\..\\escape","\\\\host\\share"}){rejected=false;try{UpdateRegistry.SafePath(root,unsafePath);}catch(IOException){rejected=true;}check(rejected,"staging rejects escaping or special path: "+unsafePath);}
            string source=Path.Combine(root,"FixtureTool.cs"),tool=Path.Combine(root,"FixtureTool.exe");File.WriteAllText(source,"using System;class Fixture{static int Main(){Console.WriteLine(\"ffmpeg version 99.0\");return 0;}}");
            string csc=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Microsoft.NET","Framework64","v4.0.30319","csc.exe");using(var process=Process.Start(new ProcessStartInfo(csc,"/nologo /platform:x64 /out:"+SshTerminal.QuoteWindowsArgument(tool)+" "+SshTerminal.QuoteWindowsArgument(source)){UseShellExecute=false,CreateNoWindow=true})){process.WaitForExit();check(process.ExitCode==0&&VendorUpdates.Is64Bit(tool),"a real x64 fixture executable is compiled for functional verification");}
            string zip=Path.Combine(root,"fixture.zip");using(var stream=File.Create(zip))using(var archive=new ZipArchive(stream,ZipArchiveMode.Create)){foreach(string name in new[]{"vendor/bin/ffmpeg.exe","vendor/bin/ffprobe.exe"}){var entry=archive.CreateEntry(name);using(var output=entry.Open())using(var input=File.OpenRead(tool))input.CopyTo(output);}var unneeded=archive.CreateEntry("vendor/bin/unapproved.dll");using(var output=unneeded.Open())output.WriteByte(42);}
            var fixture=new VendorUpdate{Id="ffmpeg",Name="FFmpeg + FFprobe",Version="99.0",FileName="fixture.zip",Url="https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-full.7z",Source="https://www.gyan.dev/ffmpeg/builds/",Hash=Digest(zip)};
            string bundled=UpdateRegistry.Resolve("media\\ffmpeg.exe");
            rejected=false;var wrong=new VendorUpdate{Id=fixture.Id,Version=fixture.Version,Url=fixture.Url,Hash=new string('b',64)};try{UpdateRegistry.Stage(wrong,zip,CancellationToken.None,delegate{});}catch(IOException){rejected=true;}check(rejected&&UpdateRegistry.State().Pending.Count==0,"mismatched package checksum never changes active or pending installation");
            rejected=false;var wrongVersion=new VendorUpdate{Id=fixture.Id,Version="98.0",Url=fixture.Url,Hash=fixture.Hash};try{UpdateRegistry.Stage(wrongVersion,zip,CancellationToken.None,delegate{});}catch(IOException){rejected=true;}check(rejected&&UpdateRegistry.State().Pending.Count==0,"functional verification rejects an executable reporting a different version");
            using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();rejected=false;try{UpdateRegistry.Stage(fixture,zip,cancellation.Token,delegate{});}catch(OperationCanceledException){rejected=true;}check(rejected&&UpdateRegistry.State().Pending.Count==0,"cancelled preparation cannot create a pending update");}
            var receipt=UpdateRegistry.Stage(fixture,zip,CancellationToken.None,delegate{});
            check(receipt.Files.Count==2&&!File.Exists(UpdateRegistry.SafePath(UpdateRegistry.SafePath(UpdateRegistry.Root,receipt.Folder),"media\\unapproved.dll")),"staging verifies and copies only the required FFmpeg and FFprobe pair");
            check(UpdateRegistry.Resolve("media\\ffmpeg.exe")==bundled&&UpdateRegistry.State().Pending.Count==1,"download preparation leaves the currently active installation unchanged");
            using(PluginIntegrity.Acquire("media\\ffmpeg.exe")){check(!UpdateRegistry.Activate("ffmpeg"),"activation is deferred while the component is leased by an operation");}
            check(UpdateRegistry.Activate("ffmpeg"),"unused verified component can be activated atomically");string active=UpdateRegistry.Resolve("media\\ffmpeg.exe");check(active!=bundled&&File.Exists(active),"runtime resolver uses the versioned update folder");
            using(MediaProcess.Acquire()){check(MediaProcess.Run("ffmpeg.exe",new[]{"-version"},CancellationToken.None,5).Contains("99.0"),"media process actually launches the activated version from its versioned folder");}
            using(PluginIntegrity.Acquire("media\\ffmpeg.exe","media\\ffprobe.exe")){rejected=false;try{File.WriteAllText(active,"tamper");}catch(IOException){rejected=true;}check(rejected,"verified files stay locked against modification during use");}
            using(ToolTrust.Acquire(active)){check(true,"external-tool trust accepts the protected verified update receipt");}
            File.AppendAllText(active,"tamper");rejected=false;try{using(PluginIntegrity.Acquire("media\\ffmpeg.exe")){} }catch(IOException){rejected=true;}check(rejected,"modified installed update is rejected rather than silently trusted");
            UpdateRegistry.Rollback("ffmpeg");check(UpdateRegistry.Resolve("media\\ffmpeg.exe")==bundled,"rollback to bundled version changes both persisted selection and runtime resolution");
            using(PluginIntegrity.Acquire("media\\ffmpeg.exe")){}check(true,"bundled file integrity remains valid after rollback");
            UpdateRegistry.Edit(state=>{state.Available=new List<VendorUpdate>{item,new VendorUpdate{Id="smart",Name="smartmontools",Version="7.5",Source=VendorUpdates.Home("smart"),Error=L.Text("updates.noChecksum")}};state.Pending.Clear();});
            main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};main.Show();NavigationTests.WaitPanels(main);
            var checkedAt=DateTime.UtcNow;UpdateRegistry.Edit(state=>{state.Daily=false;state.LastAttemptUtc=checkedAt;});NavigationTests.Wait(main.Updates.Check(true));check(UpdateRegistry.State().LastAttemptUtc==checkedAt&&!main.Updates.Checking,"disabled daily checks do not fetch metadata");UpdateRegistry.Edit(state=>state.Daily=true);NavigationTests.Wait(main.Updates.Check(true));check(UpdateRegistry.State().LastAttemptUtc==checkedAt&&!main.Updates.Checking,"recent daily check is not repeated before its interval expires");
            settings=new ConfigurationDialog(main,L.Text("updates.title")){WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};settings.Show();NavigationTests.Wait(Task.Delay(120));settings.UpdateLayout();
            check(settings.Sections.Items.Count==8&&settings.Sections.SelectedIndex==7,"updates is the eighth settings section and can be opened directly");
            check(settings.UpdatePage.Items.Items.Count==7,"settings inventories four vendor components, OpenMP image engine, libraries and application");
            settings.UpdatePage.Items.SelectedItem=settings.UpdatePage.Items.Items.Cast<UpdateRow>().Single(x=>x.Id=="imagemagick");check(!FluentUiTests.Children<Button>(settings.UpdatePage).Single(x=>Convert.ToString(x.Content)==L.Text("updates.download")).IsEnabled&&FluentUiTests.Children<TextBlock>(settings.UpdatePage).Any(x=>x.Text==L.Text("updates.imageMagickHelp")),"OpenMP engine is versioned and updated with its runtime as part of the application, not as an FFmpeg hot update");
            check(!FluentUiTests.Children<ScrollViewer>(settings.UpdatePage.Items).Any(x=>x.ComputedHorizontalScrollBarVisibility==Visibility.Visible),"update inventory fits without a horizontal scrollbar");
            settings.UpdatePage.Items.SelectedItem=settings.UpdatePage.Items.Items.Cast<UpdateRow>().Single(x=>x.Id=="app");check(!FluentUiTests.Children<Button>(settings.UpdatePage).Single(x=>Convert.ToString(x.Content)==L.Text("updates.download")).IsEnabled,"unconfigured application source cannot download or invent a GitHub release");
            settings.UpdatePage.Items.SelectedItem=settings.UpdatePage.Items.Items.Cast<UpdateRow>().Single(x=>x.Id=="smart");check(!FluentUiTests.Children<Button>(settings.UpdatePage).Single(x=>Convert.ToString(x.Content)==L.Text("updates.download")).IsEnabled,"SMART without a publisher SHA-256 is explicitly excluded from automatic installation");
            NextStageTests.Draw(settings,Path.Combine(root,"updates-settings.png"));settings.Close();settings=null;main.Close();main=null;
            if(live){
                var all=new List<VendorUpdate>();foreach(string id in VendorUpdates.Ids){var release=VendorUpdates.Check(id,CancellationToken.None);all.Add(release);check(!String.IsNullOrEmpty(release.Version),id+": live publisher metadata returned a real version");}
                UpdateRegistry.Edit(state=>state.Available=all);var seven=all.Single(x=>x.Id=="7zip");check(!String.IsNullOrEmpty(seven.Hash),"7-Zip official repository publishes its package digest");string download=Path.Combine(root,seven.FileName);using(var output=File.Create(download))UpdateNetwork.Download(seven.Url,output,64L*1048576,CancellationToken.None);check(Digest(download)==seven.Hash,"live 7-Zip package matches publisher SHA-256");var package=UpdateRegistry.Stage(seven,download,CancellationToken.None,delegate{});check(package.Files.Count==2,"official 7-Zip installer is extracted without running the installer and passes executable version verification");
                check(UpdateRegistry.Activate("7zip",true)&&ArchiveEngine.SevenZipLibraryPath.StartsWith(UpdateRegistry.Root,StringComparison.OrdinalIgnoreCase),"next-start activation resolves the downloaded official 7-Zip library");check(ArchiveEngine.Open(download,null,CancellationToken.None).Items.Any(x=>x.Path.EndsWith("7z.dll",StringComparison.OrdinalIgnoreCase)),"archive worker can use the newly activated official 7-Zip library");
                main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};main.Show();NavigationTests.WaitPanels(main);settings=new ConfigurationDialog(main,L.Text("updates.title")){WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};settings.Show();NavigationTests.Wait(Task.Delay(120));settings.UpdateLayout();NextStageTests.Draw(settings,Path.Combine(root,"updates-live-settings.png"));settings.Close();settings=null;main.Close();main=null;
            }
            string index=Path.Combine(AppPaths.ConfigDirectory,"updates.xml");byte[] indexBytes=File.ReadAllBytes(index);File.AppendAllText(index,"tampered");var broken=UpdateRegistry.State();check(!broken.Daily&&UpdateRegistry.StateError.Length>0,"corrupt update index disables updates without trusting altered state");rejected=false;try{UpdateRegistry.Edit(x=>x.Daily=true);}catch(IOException){rejected=true;}check(rejected,"invalid update state is preserved instead of silently overwritten");File.WriteAllBytes(index,indexBytes);check(UpdateRegistry.State().Available.Count>0&&UpdateRegistry.StateError.Length==0,"restoring the authentic update index recovers normal operation");
            File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
        }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}
        finally{if(settings!=null)settings.Close();if(main!=null)main.Close();}
    }
 }
}
#endif
